 3	final class BinarySearch {
 4	    private static final int NOT_FOUND = -1;
 5	    private static final int[] SAMPLE_VALUES = { 2, 3, 4, 10, 40 };
 6	    private static final int SAMPLE_TARGET = 10;
 7	
 8	    private BinarySearch() {
 9	    }
10	
11	    static int binarySearch(int[] arr, int target) {
12	        return search(arr, target).toLegacyIndex();
13	    }
14	
15	    public static void main(String[] args) {
16	        SearchResult result = search(SAMPLE_VALUES, SAMPLE_TARGET);
17	
18	        System.out.println(result.message());
19	    }
