21	    private static SearchResult search(int[] arr, int target) {
22	        int low = 0;
23	        int high = arr.length - 1;
24	
25	        while (low <= high) {
26	            int middleIndex = low + (high - low) / 2;
27	            int middleValue = arr[middleIndex];
28	
29	            if (middleValue == target) {
30	                return SearchResult.foundAt(middleIndex);
31	            }
32	
33	            if (middleValue < target) {
34	                low = middleIndex + 1;
35	            } else {
36	                high = middleIndex - 1;
37	            }
38	        }
39	
40	        return SearchResult.notFound();
41	    }
42	
43	    private record SearchResult(OptionalInt index) {
44	        private static SearchResult foundAt(int index) {
45	            return new SearchResult(OptionalInt.of(index));
46	        }
47	
48	        private static SearchResult notFound() {
49	            return new SearchResult(OptionalInt.empty());
50	        }
51	
52	        private int toLegacyIndex() {
53	            return index.orElse(NOT_FOUND);
54	        }
55	
56	        private String message() {
57	            return index.isPresent()
58	                    ? "Element is present at index " + index.getAsInt()
59	                    : "Element is not present in array";
60	        }
61	    }
